          VocabularyEntry("Exothermic vs Endothermic", "ΔH < 0 releases heat to surroundings (warming tube); ΔH > 0 absorbs heat (chilling tube).", "Heat exit (−) vs Heat entry (+).", "Combustion & Neutralization are ALWAYS exothermic!"),
          VocabularyEntry("Hess's Law", "Total enthalpy change depends ONLY on initial & final states, regardless of route.", "Altitude climb between base camp and summit equals sum of legs.", "ΔH_rxn = Σ ΔH_f(products) − Σ ΔH_f(reactants)."),
          VocabularyEntry("Entropy (ΔS)", "Measure of molecular disorder/randomness (Gas > Liquid > Solid).", "How spread out particles & energy sit.", "Melting, boiling, dissolving, and raising gas moles increase +ΔS!"),
          VocabularyEntry("Gibbs Free Energy (ΔG)", "ΔG = ΔH − TΔS determining true spontaneity (ΔG < 0 spontaneous).", "Net thermodynamic go-ahead balancing heat vs disorder.", "Even endothermic reactions go spontaneously at high T if ΔS > 0!"),
        ),
        mech1 = "Bond BREAKING always absorbs energy (+Endothermic), while bond MAKING always releases energy (−Exothermic). A reaction is exothermic overall whenever forming strong new product bonds releases MORE heat than breaking reactant bonds cost: ΔH = Bonds Broken − Bonds Made!",
        mech2 = "Standard enthalpy of neutralization between ANY strong acid and strong alkali stays steady around −57.3 kJ/mol because the net reaction is always strictly H⁺(aq) + OH⁻(aq) → H₂O(l); weak acids drop below 57.3 because part of that energy must pry apart unbroken weak acid molecules!",
        intel1 = "JAMB tests ΔG = ΔH − TΔS spontaneity sign tables, bond-energy ΔH = Broken − Made, and predicting +ΔS vs −ΔS from state symbols.",
        intel2 = "WAEC Paper 2 checks defining Enthalpy of Combustion/Neutralization (per 1 mole!) and drawing labelled Exothermic vs Endothermic energy profile diagrams.",
        recap1 = "Bond math: ΔH = Σ(Reactants Broken) − Σ(Products Formed).",
        recap2 = "Always match Units! Convert ΔS from J/K to kJ/K (÷1000) before computing ΔG = ΔH − TΔS!",
        sec3Title = "3. Born-Haber / Hess Cycles & Neutralization Magnitude",
        sec3Body = "Using Hess's Law cycles, combustion data subtracts opposite from formation data: ΔH_rxn = Σ ΔH_c(reactants) − Σ ΔH_c(products), whereas formation data does Products − Reactants! On energy profiles, ΔH measures Start-to-Finish height, while Activation Energy Ea measures Start-to-Peak hump.",
        sec3Formula = "\\Delta G = \\Delta H - T\\Delta S   |   \\Delta H = \\sum E_{\\text{broken}} - \\sum E_{\\text{formed}}",
        sec3Tip = "Never forget ΔS is almost ALWAYS printed in J·mol⁻¹K⁻¹ while ΔH is in kJ/mol—DIVIDE ΔS by 1000 before multiplying by Kelvin T!",
        sec3Mech = "Mixing kJ and J explodes TΔS by 1000× and flips ΔG signs backward!",
        sec3Intel = "JAMB tests the unit trap ΔH (kJ) vs ΔS (J) relentlessly.",
        sec3Recap = "Check units: kJ − T × (J/1000)!",
        sec4Title = "4. Cooking Gas Calorific Values & Instant Cold Packs",
        sec4Body = "LPG propane/butane burns cleanly with massive −2220 kJ/mol exothermic heat for Nigerian kitchens, whereas dissolving ammonium nitrate NH₄NO₃ fertilizer in sports cold-packs pulls ΔH > 0 heat from water (+ΔS entropy drives dissolving spontaneously even while turning freezing cold!).",
        sec4Tip = "NH₄NO₃ dissolving feels icy cold yet occurs spontaneously because +ΔS disorder wins at room T!",
        sec5Title = "5. Gibbs Unit & Per-Mole Standard Definition Check",
        sec5Body = "Read standard enthalpy definitions strictly: Combustion burns 1 mole substance completely in O₂; Formation forms 1 mole compound from elements; Neutralization forms 1 mole H₂O! Divide raw heat Q by moles reacted before quoting kJ/mol.",
        sec5Tip = "Check ΔG < 0 spontaneous; ΔG = 0 equilibrium; ΔG > 0 non-spontaneous.",
        misc1 = MisconceptionAnalysis("Exothermic reactions have ΔH > 0 because temperature in the beaker goes UP.", "Rising thermometer feels '+'.", "ΔH measures energy inside the CHEMICALS! Giving heat out to the beaker lowers chemical energy content → ΔH < 0 (Negative).", "Surroundings warm up = Chemicals lost energy (ΔH < 0)."),
        misc2 = MisconceptionAnalysis("ΔH_rxn = Σ Products − Σ Reactants works for Bond Energies too.", "Same order as ΔH_f.", "Bond Energies use REACTANTS BROKEN (+) MINUS PRODUCTS MADE (−)!", "Formation = P − R; Bonds & Combustion = R − P."),
        guidedPrompt = "For a reaction at 298 K, ΔH = +30 kJ/mol and ΔS = +150 J/(mol·K). Calculate ΔG in kJ/mol and state whether the reaction is spontaneous at 298 K.",
        guidedHints = listOf(
