        sec3Formula = "K_c = \\frac{[C]^c[D]^d}{[A]^a[B]^b} \\quad (\\text{gases/aqueous only})",
        sec3Tip = "If left and right sides hold EQUAL gas moles (e.g., H₂ + I₂ ⇌ 2HI), changing Pressure shifts NOTHING!",
