        sec5Tip = "Always verify catalyst leaves ΔH untouched on potential-energy profile diagrams!",
        misc1 = MisconceptionAnalysis("Adding a catalyst increases equilibrium product yield.", "Catalysts make more product faster.", "Catalysts lower Ea for BOTH forward AND backward reactions identically—reaching the exact same final yield sooner!", "Catalysts alter time taken, NOT equilibrium % yield."),
        misc2 = MisconceptionAnalysis("At dynamic equilibrium, forward and reverse reactions have completely stopped.", "Concentrations look frozen.", "Both reactions continue racing at EQUAL opposite rates (Rate_f = Rate_r > 0)!", "Microscopic motion continues; macroscopic amounts stay steady."),
        guidedPrompt = "Consider 2SO₂(g) + O₂(g) ⇌ 2SO₃(g), ΔH = −197 kJ/mol. Predict the effect on [SO₃] yield and K_c when (a) pressure increases, (b) V₂O₅ catalyst is added, and (c) temperature increases.",
