      "chem_09_redox_cells" to spec(
        prereq = listOf("chem_03_periodic_bonding (ion charges)"),
        dep = "Oxidation numbers and E⁰ cell voltages lead straight into Faraday Electrolysis and Metal Extraction.",
        vocab = listOf(
          VocabularyEntry("OIL RIG", "Oxidation Is Loss of electrons (Ox. No ↑); Reduction Is Gain (Ox. No ↓).", "Electron & Oxidation-Number tracker.", "Redox ALWAYS pairs oxidation and reduction simultaneously!"),
          VocabularyEntry("Oxidizing vs Reducing Agent", "Oxidizing agent accepts electrons (gets REDUCED); Reducing agent donates electrons (gets OXIDIZED).", "Agent causes the change to its PARTNER by undergoing the opposite!", "KMnO₄ / K₂Cr₂O₇ oxidize; H₂S / SO₂ / Fe²⁺ reduce."),
          VocabularyEntry("Salt Bridge", "Filter paper soaked in KNO₃ / KCl linking two half-cells.", "Completes ionic circuit without mixing solutions.", "Maintains electrical neutrality as ions migrate."),
