        ),
        mech1 = "Any reaction where at least one element changes oxidation number is Redox; double-decomposition precipitations (Ag⁺ + Cl⁻ → AgCl) and acid-base neutralizations keep every oxidation number frozen—making them NON-REDOX!",
        mech2 = "In a galvanic cell (Zn | Zn²⁺ || Cu²⁺ | Cu), the more reactive metal (more negative E⁰, Zn = −0.76 V) oxidizes at the ANODE releasing electrons up the wire to the CATHODE (Cu²⁺ = +0.34 V), producing E⁰_cell = +0.34 − (−0.76) = +1.10 V!",
        intel1 = "JAMB tests computing oxidation numbers in Cr₂O₇²⁻, MnO₄⁻, ClO₃⁻, Fe(CN)₆³⁻, identifying colour changes (purple MnO₄⁻ → colourless; orange Cr₂O₇²⁻ → green), and E⁰_cell.",
        intel2 = "WAEC Paper 2 tests balancing acidic redox half-equations with H⁺/H₂O/e⁻ and drawing IUPAC cell notation.",
        recap1 = "AN OX (Anode = Oxidation) and RED CAT (Reduction = Cathode) in EVERY cell!",
        recap2 = "Acidified KMnO₄ turns purple → colourless; K₂Cr₂O₇ turns orange → green.",
        sec3Title = "3. Half-Equation Balancing & Galvanic vs Electrolytic Polarity",
        sec3Body = "Notice the subtle polarity twist: Oxidation is ALWAYS Anode and Reduction ALWAYS Cathode (AN OX / RED CAT!). In a spontaneous GALVANIC battery, Anode creates electrons so Anode is NEGATIVE (−); in a battery-driven ELECTROLYTIC tank, external power pulls electrons out of Anode making Anode POSITIVE (+)!",
        sec3Formula = "E^\\circ_{\\text{cell}} = E^\\circ_{\\text{cathode}} - E^\\circ_{\\text{anode}}   |   \\text{Sum Ox. Nos} = \\text{Net Ion Charge}",
        sec3Tip = "Use H= +1 (except −1 in NaH metal hydrides!), O= −2 (except −1 in H₂O₂ peroxides and +2 in OF₂!).",
        sec3Mech = "Because Fluorine is MORE electronegative than Oxygen, F takes −1 in OF₂ forcing O = +2!",
        sec3Intel = "JAMB loves testing peroxide H₂O₂ (O = −1) and hydride NaH (H = −1) exceptions.",
        sec3Recap = "Galvanic battery: Spontaneous E⁰ > 0 (Anode −, Cathode +).",
        sec4Title = "4. Dry-Cell Zinc Cans, Car Lead-Acid Batteries & Breathalyzers",
        sec4Body = "Your motorcycle/car 12 V lead-acid battery reverses spontaneously between discharge (Pb + PbO₂ + H₂SO₄ → PbSO₄) and charging via alternator. Roadside breathalyzers turn orange Cr₂O₇²⁻ green when ethanol vapour reduces Chromium(+6) down to Chromium(+3)!",
        sec4Tip = "H₂S acts strictly as a REDUCING agent (sulphur −2 can only oxidize UP to 0 or +4/+6, never lower!).",
        sec5Title = "5. Disproportionation & Non-Redox Trap Check",
        sec5Body = "Always verify total oxidation number sum equals ion charge (not 0 for polyatomic ions like SO₄²⁻ = −2!). Watch out for Disproportionation where ONE species simultaneously rises and drops in oxidation number (e.g., Cl₂ + 2OH⁻ → Cl⁻(−1) + ClO⁻(+1) + H₂O!).",
        sec5Tip = "Neutralization H⁺ + OH⁻ → H₂O keeps H=+1, O=−2 unchanged → NEVER Redox!",
        misc1 = MisconceptionAnalysis("Every chemical reaction is a redox reaction.", "Electrons make bonds.", "Precipitation (Ba²⁺+SO₄²⁻→BaSO₄) and acid-base (NaOH+HCl) keep all oxidation numbers frozen—they are NON-REDOX!", "Check at least two elements' oxidation numbers before calling redox."),
        misc2 = MisconceptionAnalysis("The species that loses electrons is the Oxidizing Agent.", "Sounds like Oxidized = Oxidizing.", "Losing electrons means IT gets oxidized—so it forces electrons onto its partner, making it the REDUCING Agent!", "Gets Oxidized = Reducing Agent; Gets Reduced = Oxidizing Agent."),
        guidedPrompt = "Find Chromium's oxidation number in Cr₂O₇²⁻, identify the oxidizing agent in Fe²⁺ + MnO₄⁻ → Fe³⁺ + Mn²⁺, and find E⁰_cell given E⁰(Zn²⁺/Zn)=−0.76 V and E⁰(Ag⁺/Ag)=+0.80 V.",
        guidedHints = listOf(
          "Hint 1: 2Cr + 7(−2) = −2 → 2Cr = +12 → Cr = +6.",
          "Hint 2: Mn drops from +7 (MnO₄⁻) to +2 (Mn²⁺) → reduced → MnO₄⁻ is the Oxidizing Agent!",
          "Hint 3: Higher E⁰ (+0.80 V Ag⁺) reduces at cathode; E⁰_cell = +0.80 − (−0.76).",
        ),
        guidedApproach = "Algebraic sum = −2 → track ΔOxNo → E⁰_cathode − E⁰_anode.",
        guidedSolution = "Cr = +6 in Cr₂O₇²⁻. MnO₄⁻ drops +7→+2 (Oxidizing agent). E⁰_cell = +0.80 − (−0.76) = +1.56 V.",
        projTitle = "Car Lead-Acid Battery vs Breathalyzer Redox Brief",
        projScenario = "Explain why a breathalyzer potassium dichromate tube switches from bright orange to green on exhaling alcohol.",
        projStages = listOf("Assign Cr oxidation state in orange Cr₂O₇²⁻ (+6) and green Cr³⁺ (+3).", "Identify ethanol as Reducing Agent.", "Explain why H₂SO₄ acidity is required."),
        projRubric = listOf("Shows +6 → +3 gain of 3e⁻ per Cr.", "Names ethanol oxidized to ethanoic acid.", "Links colour shift to reduction of Cr(+6)."),
        projModel = "Ethanol reduces orange Cr₂O₇²⁻ (Cr +6) in acidic medium down to green Cr³⁺ (Cr +3), oxidizing ethanol to ethanoic acid—providing direct visible measurement of blood-alcohol exposure.",
        cheatOverview = "OIL RIG; AN OX / RED CAT; E⁰_cell = E⁰_red − E⁰_ox > 0.",
        cheatLegend = listOf("H=+1 (NaH −1)", "O=−2 (H₂O₂ −1)", "MnO₄⁻: Purple→Clear", "Cr₂O₇²⁻: Orange→Green"),
        cheatTraps = listOf("Calling Oxidized species Oxidizing Agent", "Forgetting charge sum = −2 on Cr₂O₇²⁻", "Calling BaSO₄ precipitation Redox"),
        cheatMemory = "AN OX / RED CAT; Agent does opposite to its name on ITSELF!",
      ),
      "chem_10_electrolysis" to spec(
        prereq = listOf("chem_09_redox_cells", "chem_04_stoichiometry_moles"),
        dep = "Selective ion discharge and Faraday Q = It = nF laws underpin Aluminium smelting, Copper refining, and Electroplating.",
        vocab = listOf(
          VocabularyEntry("Selective Discharge Rules", "Three checks: (1) Electrode potential E⁰ position, (2) Ion concentration, (3) Reactive vs inert electrode.", "Who wins exit ticket at cathode/anode.", "K⁺, Na⁺, Ca²⁺, Mg²⁺, Al³⁺ NEVER discharge from water—H⁺ wins!"),
          VocabularyEntry("Faraday Constant (F)", "Charge of 1 mole of electrons ≈ 96,500 Coulombs/mol.", "Electrical currency price for 1 mole of single-charge ions.", "Requires z Faradays (z \\times 96,500\\text{ C}) to plate 1 mole of M^{z+}!"),
          VocabularyEntry("1st & 2nd Faraday Laws", "Mass m ∝ Q = It; For same Q, moles plated ∝ 1 / ion charge z.", "More current/time = thicker plate; higher valency takes MORE charge!", "Mass m = (I · t · M_r) / (z · 96,500)."),
          VocabularyEntry("Inert vs Active Electrode", "Platinum/Graphite watch passively vs Copper anode dissolving into Cu²⁺.", "Spectator plate vs sacrificial metal electrode.", "Purifying blister copper uses IMPURE Cu anode → PURE Cu cathode!"),
        ),
        mech1 = "In aqueous CuSO₄ with PLATINUM electrodes, Cu²⁺ plates cathode (leaving H⁺) and OH⁻ discharges O₂ gas (leaving blue colour fading & solution turning acidic H₂SO₄!). Swap to COPPER electrodes and the copper anode dissolves faster than OH⁻, keeping blue Cu²⁺ colour frozen steady!",
        mech2 = "Electroplating 1 mole of Al³⁺ needs THREE moles of electrons (3 × 96,500 C), whereas 1 mole of Ag⁺ needs just ONE Faraday—explaining why identical current deposits 3× more moles of Silver than Aluminium!",
        intel1 = "JAMB tests m = MIt/(zF) mass & gas volume at STP, series cells comparing Ag⁺/Cu²⁺/Al³⁺ mole ratios (6:3:2!), and brine NaCl(conc) → Cl₂ vs H₂ + leftover NaOH!",
        intel2 = "WAEC Paper 2 checks electroplating setup (object MUST be CATHODE!) and contrasting CuSO₄(aq) with Pt vs Cu electrodes.",
        recap1 = "To electroplate a spoon: Spoon = CATHODE (−), Plating Metal = ANODE (+), Electrolyte = Salt of Plating Metal.",
        recap2 = "Charge Q = I × t (t strictly in SECONDS!).",
        sec3Title = "3. Brine vs Dilute H₂SO₄ & Copper Refining Series Cells",
        sec3Body = "Concentrated brine NaCl(aq) discharges Cl₂ at anode (high [Cl⁻] overrides OH⁻!) and H₂ at cathode (H⁺ beats Na⁺), turning leftover bath into industrial NaOH! Dilute H₂SO₄ electrolyzes water cleanly producing 2 volumes H₂ (cathode) : 1 volume O₂ (anode). In series cells passing equal Q, mole ratio deposited is Ag : Cu : Al = 1 : 1/2 : 1/3 = 6 : 3 : 2.",
        sec3Formula = "Q = I t   |   m = \\frac{M_r I t}{z F}   |   n_{\\text{e}^-} = \\frac{Q}{96,500}",
        sec3Tip = "Check time units EVERY time! 32 minutes 10 seconds = (32×60 + 10) = 1,930 s (0.02×96500!).",
        sec3Mech = "WAEC loves clean Faraday multiples like 1930 s or 965 s specifically to divide neatly by 96,500!",
        sec3Intel = "NECO/JAMB frequently ask what happens to pH of brine or CuSO₄(aq) with inert Pt electrodes during electrolysis.",
        sec3Recap = "Concentrated Cl⁻ beats OH⁻ → Cl₂; Dilute halides lose to OH⁻ → O₂.",
        sec4Title = "4. Silver Cutlery Plating & Aluminium Pot Smelting",
        sec4Body = "Artisans electroplating brass spoons make the spoon the negative CATHODE inside AgNO₃(aq) with a pure Silver ANODE so silver ions plate evenly without peeling. Copper electrical wires are refined to 99.99% purity identically.",
        sec4Tip = "Object to be plated ALWAYS goes to the CATHODE!",
        sec5Title = "5. Valency z & Gas STP Faraday Check",
        sec5Body = "Beware of O₂(g) at the anode: 4OH⁻ → 2H₂O + O₂ + 4e⁻ requires FOUR Faradays per 1 mole (22.4 dm³) of O₂, NOT two! Meanwhile H₂(g) and Cl₂(g) need TWO Faradays per mole (22.4 dm³).",
        sec5Tip = "1 Faraday liberates: 1 mol Ag; ½ mol Cu; ⅓ mol Al; ½ mol H₂/Cl₂ (11.2 dm³); ¼ mol O₂ (5.6 dm³)!",
        misc1 = MisconceptionAnalysis("Solid NaCl and aqueous sugar solution conduct electricity because they contain ions or dissolve cleanly.", "Both look mobile or salt-like.", "Solid NaCl locks ions rigid; Sugar is covalent with ZERO ions! Neither conducts electricity.", "Conduction requires FREE MOBILE electrons (metals) or FREE MOBILE IONS (molten/aqueous salts/acids)."),
        misc2 = MisconceptionAnalysis("1 Faraday produces 11.2 dm³ of Oxygen just like Hydrogen and Chlorine.", "Assuming all diatomic gases are z=2.", "2H⁺ + 2e⁻ → H₂ (2F/mol → 11.2 dm³/F), whereas 4OH⁻ → O₂ + 2H₂O + 4e⁻ needs 4F/mol → 5.6 dm³ O₂ per Faraday!", "Always write the balanced gas half-equation for z."),
        guidedPrompt = "A steady current of 2.0 A passes through molten Al₂O₃ for 965 seconds. Calculate the mass of Aluminium deposited at the cathode (Al=27, F=96,500 C/mol).",
        guidedHints = listOf(
          "Hint 1: Q = I × t = 2.0 × 965 = 1,930 C.",
