        projTitle = "99.99% Blister Copper Refining Tank Design Note",
        projScenario = "Specify electrodes, electrolyte, and impurity fate for electrolytic refining of impure Nigerian copper ore.",
        projStages = listOf("Assign impure blister block = Anode (+), thin pure sheet = Cathode (−).", "Select acidified CuSO₄(aq) electrolyte.", "Trace anode sludge (Ag/Au) vs dissolved less-noble Zn/Fe²⁺."),
        projRubric = listOf("Correctly assigns Cathode = pure Cu.", "Explains blue Cu²⁺ stays constant.", "Accounts for noble Ag/Au dropping as valuable anode slime."),
        projModel = "Impure Cu block at Anode oxidizes Cu → Cu²⁺(aq); pure Cu²⁺ plates onto pure Cu Cathode. Reactive Zn/Fe impurities remain harmlessly in solution while precious Ag/Au sink beneath the anode as recoverable anode slime.",
        cheatOverview = "Q=It; m = MIt/(zF); 1F = 96,500 C; Plated object = Cathode.",
