        vocab = listOf(
          VocabularyEntry("Water Hardness", "Presence of Ca²⁺ or Mg²⁺ ions preventing soap lather (forming scum).", "Mineral lock blocking soap foam.", "Temporary (HCO₃⁻) boils soft; Permanent (SO₄²⁻/Cl⁻) needs Na₂CO₃ or resin!"),
