          VocabularyEntry("Fountain Experiment", "Vacuum suction fountain proving extreme water solubility of NH₃ or HCl gas.", "Gas vanishes into one drop, sucking liquid skyward.", "NH₃ turns phenolphthalein pink; HCl turns blue litmus red."),
