        intel1 = "JAMB tests matching drying agents (conc. H₂SO₄ CANNOT dry basic NH₃ or reducing H₂S; CaO dries NH₃!), gas collection (upward/downward delivery), and Cl₂ vs SO₂ bleaching.",
        intel2 = "WAEC Paper 2 checks municipal water purification stages (Coagulation with Alum → Sedimentation → Sand Filtration → Chlorination) and Haber/Contact/Solvay equations.",
        recap1 = "Cl₂ bleaches permanently by OXIDATION; SO₂ bleaches temporarily by REDUCTION.",
        recap2 = "Dry NH₃ strictly with CaO (Quicklime)—conc. H₂SO₄ reacts to form (NH₄)₂SO₄ salt!",
        sec3Title = "3. Halogen Trends, Gas Drying Agents & Allotropes",
        sec3Body = "Down Group 7 (F₂ gas → Cl₂ green gas → Br₂ red liquid → I₂ purple-black solid): colour darkens, b.p. rises, and oxidizing/displacement power WEAKENS (Cl₂ displaces Br⁻ and I⁻ cleanly; I₂ cannot displace Cl⁻!). Acidic gases (HCl, SO₂, CO₂, Cl₂) dry over conc. H₂SO₄; neutral gases (H₂, O₂, N₂) over CaCl₂/H₂SO₄; alkaline NH₃ strictly over CaO!",
        sec3Formula = "\\text{Ca(HCO}_3)_2 \\xrightarrow{\\Delta} \\text{CaCO}_3\\!\\downarrow + \\text{H}_2\\text{O} + \\text{CO}_2   |   \\text{NH}_3 + \\text{HCl} \\rightarrow \\text{NH}_4\\text{Cl(s)}",
        sec3Tip = "CO and CO₂ both react cleanly differently: CO is NEUTRAL (doesn't turn limewater milky, reduces hot CuO); CO₂ turns limewater milky CaCO₃ (excess soluble Ca(HCO₃)₂ clears again!).",
        sec3Mech = "Excess CO₂ dissolves white CaCO₃ back into soluble Ca(HCO₃)₂, turning milky limewater clear again if bubbled too long!",
        sec3Intel = "WAEC practically ALWAYS checks why 'excess CO₂ clears milky limewater' and why conc. H₂SO₄ fails for NH₃/H₂S.",
        sec3Recap = "Cl₂ > Br₂ > I₂ displacement strength; Upward delivery = light gases (H₂, NH₃); Downward = dense (Cl₂, CO₂, SO₂).",
        sec4Title = "4. Municipal Waterworks Alum-Chlorination & Kettle Fur",
        sec4Body = "Lagos/Abuja state water boards dose muddy raw river water with Alum (coagulates clay flocs), settle, filter through sand beds, add Chlorine (kills cholera/typhoid bacteria), and adjust pH with Ca(OH)₂ before distribution.",
        sec4Tip = "Chlorine kills germs; Alum settles suspended mud; Washing soda softens permanent hardness!",
        sec5Title = "5. Gas Identification & Acid-Rain Checks",
        sec5Body = "Remember: HCl fumes in moist air and forms white NH₄Cl with NH₃; SO₂ & H₂S decolourize acidified purple KMnO₄ AND orange K₂Cr₂O₇ (H₂S deposits yellow sulphur!); NO₂ is brown acidic pungent gas turning wet blue litmus red.",
        sec5Tip = "Never say H₂S is odourless—rotten-egg smell & blackens moist Pb(NO₃)₂ paper to PbS!",
        misc1 = MisconceptionAnalysis("Concentrated H₂SO₄ is a universal drying agent for all gases.", "Most powerful dehydrator.", "Conc. H₂SO₄ is an ACID and OXIDIZER—so it neutralizes alkaline NH₃ and oxidizes H₂S/HI instead of drying them!", "Match drying agent acidity to gas: NH₃ → CaO; H₂S → CaCl₂/P₄O₁₀."),
        misc2 = MisconceptionAnalysis("Both Cl₂ and SO₂ bleach damp litmus paper by the exact same chemical process.", "Both turn paper white.", "Cl₂ bleaches permanently via Oxidation (HOCl); SO₂ bleaches temporarily via Reduction (air slowly reverses SO₂ bleaching!).", "Contrast Permanent Oxidation (Cl₂) vs Temporary Reduction (SO₂)."),
        guidedPrompt = "A student bubbles gas X into acidified potassium dichromate(VI) turning it orange→green, and observes moist blue litmus turning red then bleached. Identify X, explain the colour changes, and explain why boiling removes Temporary but not Permanent water hardness.",
