        sec3Formula = "\\text{C}_n\\text{H}_{2n+2}\\; (\\text{Alkane})   |   \\text{C}_n\\text{H}_{2n}\\; (\\text{Alkene})   |   \\text{C}_n\\text{H}_{2n-2}\\; (\\text{Alkyne})",
